/* Signify 城市定位：离线经纬度 → 最近城市（无需外网 API / 备案） */
(function () {
  /* [城市, 纬度, 经度] 主要城市中心点 */
  var CITIES = [
    ['北京', 39.90, 116.40], ['上海', 31.23, 121.47], ['天津', 39.13, 117.20],
    ['重庆', 29.56, 106.55], ['广州', 23.13, 113.26], ['深圳', 22.54, 114.06],
    ['杭州', 30.27, 120.16], ['南京', 32.06, 118.80], ['苏州', 31.30, 120.58],
    ['无锡', 31.49, 120.31], ['武汉', 30.59, 114.31], ['长沙', 28.23, 112.94],
    ['成都', 30.57, 104.07], ['西安', 34.34, 108.94], ['郑州', 34.75, 113.63],
    ['济南', 36.65, 117.12], ['青岛', 36.07, 120.38], ['烟台', 37.46, 121.45],
    ['沈阳', 41.80, 123.43], ['大连', 38.91, 121.61], ['长春', 43.82, 125.32],
    ['哈尔滨', 45.80, 126.53], ['合肥', 31.82, 117.23], ['福州', 26.07, 119.30],
    ['厦门', 24.48, 118.09], ['泉州', 24.87, 118.60], ['南昌', 28.68, 115.86],
    ['南宁', 22.82, 108.32], ['海口', 20.04, 110.32], ['三亚', 18.25, 109.51],
    ['石家庄', 38.04, 114.51], ['太原', 37.87, 112.55], ['呼和浩特', 40.84, 111.75],
    ['兰州', 36.06, 103.83], ['西宁', 36.62, 101.78], ['银川', 38.49, 106.23],
    ['乌鲁木齐', 43.83, 87.62], ['昆明', 25.04, 102.71], ['贵阳', 26.65, 106.63],
    ['拉萨', 29.65, 91.14], ['佛山', 23.02, 113.12], ['东莞', 23.02, 113.75],
    ['珠海', 22.27, 113.58], ['中山', 22.52, 113.39], ['宁波', 29.87, 121.54],
    ['温州', 28.00, 120.67], ['香港', 22.32, 114.17], ['澳门', 22.20, 113.55],
    ['台北', 25.03, 121.57], ['新北', 25.01, 121.47], ['高雄', 22.62, 120.31],
    ['台中', 24.15, 120.67], ['台南', 22.99, 120.21], ['桃园', 24.99, 121.31]
  ];

  function nearest(lat, lng) {
    var best = null, bestD = Infinity, d;
    for (var i = 0; i < CITIES.length; i++) {
      d = Math.pow(CITIES[i][1] - lat, 2) + Math.pow(CITIES[i][2] - lng, 2);
      if (d < bestD) { bestD = d; best = CITIES[i][0]; }
    }
    return best;
  }

  function locate() {
    var btn = document.getElementById('locate-btn');
    var input = document.getElementById('city-input');
    var label = document.getElementById('locate-label');
    var setStatus = function (t) { if (label) label.textContent = t; };
    if (!btn || !input) return;
    if (!navigator.geolocation) { setStatus('不支持定位'); return; }

    setStatus('定位中…');
    navigator.geolocation.getCurrentPosition(function (pos) {
      input.value = nearest(pos.coords.latitude, pos.coords.longitude);
      /* 派发 input 事件，让 Alpine x-model 同步新值 */
      input.dispatchEvent(new Event('input', { bubbles: true }));
      setStatus('定位');
    }, function () {
      setStatus('定位失败');
      setTimeout(function () { setStatus('定位'); }, 2000);
    }, { timeout: 8000, maximumAge: 600000 });
  }

  var btn = document.getElementById('locate-btn');
  if (btn) btn.addEventListener('click', locate);
})();
